create or replace view v_kpi_trends with(security_invoker=true)as with daily_base as(select distinct on(r.kpi_definition_id,r.production_date,coalesce(r.production_area_id,'00000000-0000-0000-0000-000000000000'::uuid))r.organization_id,r.kpi_definition_id,r.production_area_id,r.production_date,r.value from kpi_results r where r.value is not null order by r.kpi_definition_id,r.production_date,coalesce(r.production_area_id,'00000000-0000-0000-0000-000000000000'::uuid),r.calculated_at desc),periods as(select organization_id,kpi_definition_id,production_area_id,'DAILY'::text period_type,production_date period_start,production_date period_end,1::bigint points,value latest_value,value average_value,value minimum_value,value maximum_value from daily_base union all select organization_id,kpi_definition_id,production_area_id,'WEEKLY',date_trunc('week',production_date)::date,(date_trunc('week',production_date)+interval'6 days')::date,count(*),(array_agg(value order by production_date desc))[1],avg(value),min(value),max(value)from daily_base group by organization_id,kpi_definition_id,production_area_id,date_trunc('week',production_date)union all select organization_id,kpi_definition_id,production_area_id,'MONTHLY',date_trunc('month',production_date)::date,(date_trunc('month',production_date)+interval'1 month-1 day')::date,count(*),(array_agg(value order by production_date desc))[1],avg(value),min(value),max(value)from daily_base group by organization_id,kpi_definition_id,production_area_id,date_trunc('month',production_date)),compared as(select p.*,lag(latest_value)over(partition by organization_id,kpi_definition_id,production_area_id,period_type order by period_start)previous_value from periods p)select c.*,latest_value-previous_value absolute_change,case when previous_value=0 then null else round((latest_value-previous_value)/abs(previous_value)*100,2)end percentage_change from compared c;revoke all on v_kpi_trends from anon,authenticated;grant select on v_kpi_trends to service_role;
